K = int(data[1])
JUMPS = list(map(int, data[2:2+K]))
Q = int(data[2+K])
RANGES = [(int(data[2+K+2*i]), int(data[2+K+2*i+1])) for i in range(Q)]

class FenwickTree:
    def __init__(self, n):
        self.n = n
        self.tree = [0] * (n + 1)

    def update(self, idx, delta):
        while idx <= self.n:
            self.tree[idx] += delta
            idx += idx & -idx

    def query(self, idx):
        result = 0
        while idx > 0:
            result += self.tree[idx]
            idx -= idx & -idx
        return result

def solve():
    ft = FenwickTree(N)
    for jump in JUMPS:
        for i in range(jump - 1, N, jump):
            ft.update(i + 1, 1)

    results = []
    for l, r in RANGES:
        results.append(ft.query(r + 1) - ft.query(l))

    for result in results:
        print(result)

solve()

import sys
input = sys.stdin.read
data = input().split()

N = int(data[0])
K = int(data[1])
JUMPS = list(map(int, data[2:2+K]))
Q = int(data[2+K])
RANGES = [(int(data[2+K+2*i]), int(data[2+K+2*i+1])) for i in range(Q)]

def update(seq, n, idx):
    while idx < n:
        seq[idx] += 1
        idx += idx & -idx

def query(seq, n, l, r):
    return sum(seq[r]) - (sum(seq[l-1]) if l > 0 else 0)

seq = [0] * (N + 1)
for jump in JUMPS:
    update(seq, N + 1, jump)

results = []
for l, r in RANGES:
    results.append(query(seq, N + 1, l, r))

for result in results:
    print(result)
